package com.bank.integrity;

import java.util.logging.*;

public class CycleDetectDemo {
    private static final Logger log = Logger.getLogger(CycleDetectDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        ChainIntegrityChecker checker = new ChainIntegrityChecker();

        TxnNode clean = TxnNode.of("T1", "T2", "T3", "T4");
        log.info(() -> "Clean chain has cycle? " + checker.hasCycle(clean));

        // Build a corrupted chain: T4 points back to T2
        TxnNode a = new TxnNode("T1"), b = new TxnNode("T2"),
                c = new TxnNode("T3"), d = new TxnNode("T4");
        a.next = b; b.next = c; c.next = d; d.next = b; // loop!
        log.info(() -> "Corrupted chain has cycle? " + checker.hasCycle(a));
    }
}

