class ChainIntegrityChecker {
    private static final Logger log = Logger.getLogger(ChainIntegrityChecker.class.getName());

    // Floyd's tortoise and hare. O(n) time, O(1) space.
    boolean hasCycle(TxnNode head) {
        TxnNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;          // +1
            fast = fast.next.next;     // +2
            if (slow == fast) {        // reference equality → structural loop
                log.warning("Cycle detected in chain");
                return true;
            }
        }
        return false;
    }
}

